-- Blog: las notas pasan a ser exactamente las del blog anterior (mujeresxmas.com, categoría
-- "Blog de noticias"). Borra las publicaciones que había (y sus comentarios) y carga esas 5 notas
-- publicadas con su fecha original. Las fotos están en public/blog/<nota>/ del repo.

insert into public.blog_categories (name, slug, description)
values ('Noticias', 'noticias', 'Novedades, alianzas y propuestas de Mujeres x Más.')
on conflict (slug) do nothing;

delete from public.blog_posts;

insert into public.blog_posts
  (title, slug, excerpt, content, content_html, reading_minutes, cover_path, cover_alt, author_name, published_at,
   category_id, status)
select v.title, v.slug, v.excerpt, v.content, v.content_html, v.reading_minutes, v.cover_path, v.cover_alt,
  v.author_name, v.published_at, (select id from public.blog_categories where slug = 'noticias'),
  'published'::public.content_status
from (values
  ('MXM y WOMEN´S ENTREPRENEURSHIP DAY', 'mxm-y-womens-entrepreneurship-day', 'MXM fue parte del evento Women´s Entrepreneurship Day organizado en la ciudad de Asunción por AMCHAM.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"MXM","marks":[{"type":"link","attrs":{"href":"https://mujeresxmas.com"}}]},{"type":"text","text":" estuvo fue para del evento "},{"type":"text","text":"WOMEN´S ENTREPRENEURSHIP DAY","marks":[{"type":"link","attrs":{"href":"https://www.womenseday.org/"}}]},{"type":"text","text":" organizado en la ciudad de Asunción por "},{"type":"text","text":"AMCHAM","marks":[{"type":"link","attrs":{"href":"https://amcham.com.ar/"}}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Un espacio creado para que todas las emprendedoras de todo el país intercambien buenas prácticas, ideas innovadoras para sus negocios y generen comunidad."}]},{"type":"paragraph","content":[{"type":"text","text":"Siempre es un gusto ser parte de espacios que convoquen a nuevas formas de trabajo, potencien conocimientos y generen redes."}]}]}'::jsonb, '<p><a target="_blank" rel="noopener noreferrer" href="https://mujeresxmas.com">MXM</a> estuvo fue para del evento <a target="_blank" rel="noopener noreferrer" href="https://www.womenseday.org/">WOMEN´S ENTREPRENEURSHIP DAY</a> organizado en la ciudad de Asunción por <a target="_blank" rel="noopener noreferrer" href="https://amcham.com.ar/">AMCHAM</a>.</p><p>Un espacio creado para que todas las emprendedoras de todo el país intercambien buenas prácticas, ideas innovadoras para sus negocios y generen comunidad.</p><p>Siempre es un gusto ser parte de espacios que convoquen a nuevas formas de trabajo, potencien conocimientos y generen redes.</p>', 1, '/blog/mxm-y-womens-entrepreneurship-day/mxm-y-womens-entrepreneurship-day.jpg', 'MXM y WOMEN´S ENTREPRENEURSHIP DAY', 'Mujeres x Más', '2022-11-30T19:39:04-03:00'::timestamptz),
  ('MUJERESXMAS SU SUMA COMO SOCIO de La Asociación de emprendedores de Argentina – ASEA', 'mujeresxmas-su-suma-como-socio-de-la-asociacion-de-emprendedores-de-argentina-asea', 'Decidimos sumarnos como socios a ASEA, la Asociación de Emprendedores de la Argentina, para aportar nuestro conocimiento y llegar a más mujeres.', '{"type":"doc","content":[{"type":"image","attrs":{"src":"/blog/mujeresxmas-su-suma-como-socio-de-la-asociacion-de-emprendedores-de-argentina-asea/asea-blogg.jpg","alt":"ASEA y Mujeres x Más","title":null}},{"type":"paragraph","content":[{"type":"text","text":"MujeresXmas","marks":[{"type":"link","attrs":{"href":"https://mujeresxmas.com"}}]},{"type":"text","text":" trabaja para que día a día nuestras seguidoras se animen a crecer, emprender, adquirir nuevos conocimientos y acceder a información relevante para su vida y su desarrollo económico ."}]},{"type":"paragraph","content":[{"type":"text","text":"En este marco decidimos sumarnos como socios a "},{"type":"text","text":"ASEA – Asociación de Emprendedores de la Argentina para sumarnos y aportar nuestro","marks":[{"type":"link","attrs":{"href":"https://www.asea.org.ar/"}}]},{"type":"text","text":" conocimiento para llegar a más mujeres."}]},{"type":"paragraph","content":[{"type":"text","text":"Nuestro objetivo es generar alianzas que potencien nuestras acciones y favorezcan a nuestra comunidad con triple impacto."}]},{"type":"paragraph","content":[{"type":"text","text":"De esta forma generamos nuevas estrategias y fortalecemos nuestras acciones."}]},{"type":"paragraph","content":[{"type":"text","text":"Sumate y conocé más de nuestra propuesta."}]},{"type":"paragraph","content":[{"type":"text","text":"Seguinos en nuestras redes"}]}]}'::jsonb, '<img loading="lazy" src="/blog/mujeresxmas-su-suma-como-socio-de-la-asociacion-de-emprendedores-de-argentina-asea/asea-blogg.jpg" alt="ASEA y Mujeres x Más"/><p><a target="_blank" rel="noopener noreferrer" href="https://mujeresxmas.com">MujeresXmas</a> trabaja para que día a día nuestras seguidoras se animen a crecer, emprender, adquirir nuevos conocimientos y acceder a información relevante para su vida y su desarrollo económico .</p><p>En este marco decidimos sumarnos como socios a <a target="_blank" rel="noopener noreferrer" href="https://www.asea.org.ar/">ASEA – Asociación de Emprendedores de la Argentina para sumarnos y aportar nuestro</a> conocimiento para llegar a más mujeres.</p><p>Nuestro objetivo es generar alianzas que potencien nuestras acciones y favorezcan a nuestra comunidad con triple impacto.</p><p>De esta forma generamos nuevas estrategias y fortalecemos nuestras acciones.</p><p>Sumate y conocé más de nuestra propuesta.</p><p>Seguinos en nuestras redes</p>', 1, '/blog/mujeresxmas-su-suma-como-socio-de-la-asociacion-de-emprendedores-de-argentina-asea/asea.jpg', 'MUJERESXMAS SU SUMA COMO SOCIO de La Asociación de emprendedores de Argentina – ASEA', 'Mujeres x Más', '2022-05-18T18:40:29-03:00'::timestamptz),
  ('Skillsbuild & MUJERESXMAS', 'skillsbuild-mujeresxmas', 'Una alianza para que más mujeres se sumen al mundo STEM: contenidos, habilidades para el trabajo e insignias profesionales, de forma gratuita.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Empieza a construir tu futuro"}]},{"type":"image","attrs":{"src":"/blog/skillsbuild-mujeresxmas/ibm-skills.png","alt":"IBM SkillsBuild","title":null}},{"type":"paragraph","content":[{"type":"text","text":"Con el objetivo de ofrecer nuevas alternativas para que más y más mujeres se sumen al mundo"},{"type":"text","text":" STEM","marks":[{"type":"link","attrs":{"href":"https://skillsbuild.org/"}}]},{"type":"text","text":", cerramos este acuerdo con una de las empresas lideres en capacitación y tecnología"}]},{"type":"paragraph","content":[{"type":"text","text":"A través de esta alianza acercamos la posibilidad de "},{"type":"text","text":"explorar nuevos contenidos","marks":[{"type":"bold"}]},{"type":"text","text":", adquirir habilidades fundamentales para el trabajo y obtener insignias profesionales para demostrar lo aprendido, todo ello de forma gratuita."}]},{"type":"paragraph","content":[{"type":"text","text":"Para ello solo debes inscribirte en nuestro sitio web y comenzar tu camino de formación ."}]},{"type":"paragraph","content":[{"type":"text","text":"REGISTRATE AHORA"}]}]}'::jsonb, '<h3>Empieza a construir tu futuro</h3><img loading="lazy" src="/blog/skillsbuild-mujeresxmas/ibm-skills.png" alt="IBM SkillsBuild"/><p>Con el objetivo de ofrecer nuevas alternativas para que más y más mujeres se sumen al mundo<a target="_blank" rel="noopener noreferrer" href="https://skillsbuild.org/"> STEM</a>, cerramos este acuerdo con una de las empresas lideres en capacitación y tecnología</p><p>A través de esta alianza acercamos la posibilidad de <strong>explorar nuevos contenidos</strong>, adquirir habilidades fundamentales para el trabajo y obtener insignias profesionales para demostrar lo aprendido, todo ello de forma gratuita.</p><p>Para ello solo debes inscribirte en nuestro sitio web y comenzar tu camino de formación .</p><p>REGISTRATE AHORA</p>', 1, '/blog/skillsbuild-mujeresxmas/banner-de-la-noticia-skillsbuild-mxm.png', 'Skillsbuild & MUJERESXMAS', 'Mujeres x Más', '2022-03-31T16:15:41-03:00'::timestamptz),
  ('Mujeres Superpoderosas', 'mujeres-superpoderosas', 'Historias reales de mujeres reales: emprendedoras latinoamericanas que creyeron en sus ideas, empezaron desde cero y hoy triunfan en lo que hacen.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Historias reales de mujeres reales"}]},{"type":"paragraph","content":[{"type":"text","text":"Desde MUJERESXMAS trabajamos para que puedas conocer mujeres que eligieron emprender, reinventarse y crecer."}]},{"type":"paragraph","content":[{"type":"text","text":"Mujeres latinoamericanas que creyeron en sus ideas, empezaron desde cero y ahora triunfan en lo que hacen."}]},{"type":"paragraph","content":[{"type":"text","text":"¿Por qué las elegimos?"}]},{"type":"paragraph","content":[{"type":"text","text":"Porque cada una de ellas tiene una gran historia para compartir, son parte de una comunidad y permanentes generadoras del cambio. Todas ellas enfrentaron desafíos, saltaron obstáculos, aprovecharon sus fortalezas y trabajaron para que sus debilidades no impidieran su crecimiento."}]},{"type":"paragraph","content":[{"type":"text","text":"¡Mes a mes te vamos a presentar a una nueva SUPERPODEROSA en nuestras redes!"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ver en Instagram","marks":[{"type":"link","attrs":{"href":"https://www.instagram.com/p/CbObaivMbEf/"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ver en Instagram","marks":[{"type":"link","attrs":{"href":"https://www.instagram.com/p/CbYhDV7rtKd/"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ver en Instagram","marks":[{"type":"link","attrs":{"href":"https://www.instagram.com/p/CfC8jr3MTSE/"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ver en Instagram","marks":[{"type":"link","attrs":{"href":"https://www.instagram.com/p/Ci_NW1GsNLO/"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ver en Instagram","marks":[{"type":"link","attrs":{"href":"https://www.instagram.com/p/CcgqgOdM5O6/"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ver en Instagram","marks":[{"type":"link","attrs":{"href":"https://www.instagram.com/p/CgK-d2MMM2m/"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ver en Instagram","marks":[{"type":"link","attrs":{"href":"https://www.instagram.com/p/CdoxweRsQew/"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ver en Instagram","marks":[{"type":"link","attrs":{"href":"https://www.instagram.com/p/ChTDNdHs6mU/"}}]}]}]}]}]}'::jsonb, '<p>Historias reales de mujeres reales</p><p>Desde MUJERESXMAS trabajamos para que puedas conocer mujeres que eligieron emprender, reinventarse y crecer.</p><p>Mujeres latinoamericanas que creyeron en sus ideas, empezaron desde cero y ahora triunfan en lo que hacen.</p><p>¿Por qué las elegimos?</p><p>Porque cada una de ellas tiene una gran historia para compartir, son parte de una comunidad y permanentes generadoras del cambio. Todas ellas enfrentaron desafíos, saltaron obstáculos, aprovecharon sus fortalezas y trabajaron para que sus debilidades no impidieran su crecimiento.</p><p>¡Mes a mes te vamos a presentar a una nueva SUPERPODEROSA en nuestras redes!</p><ul><li><p><a target="_blank" rel="noopener noreferrer" href="https://www.instagram.com/p/CbObaivMbEf/">Ver en Instagram</a></p></li><li><p><a target="_blank" rel="noopener noreferrer" href="https://www.instagram.com/p/CbYhDV7rtKd/">Ver en Instagram</a></p></li><li><p><a target="_blank" rel="noopener noreferrer" href="https://www.instagram.com/p/CfC8jr3MTSE/">Ver en Instagram</a></p></li><li><p><a target="_blank" rel="noopener noreferrer" href="https://www.instagram.com/p/Ci_NW1GsNLO/">Ver en Instagram</a></p></li><li><p><a target="_blank" rel="noopener noreferrer" href="https://www.instagram.com/p/CcgqgOdM5O6/">Ver en Instagram</a></p></li><li><p><a target="_blank" rel="noopener noreferrer" href="https://www.instagram.com/p/CgK-d2MMM2m/">Ver en Instagram</a></p></li><li><p><a target="_blank" rel="noopener noreferrer" href="https://www.instagram.com/p/CdoxweRsQew/">Ver en Instagram</a></p></li><li><p><a target="_blank" rel="noopener noreferrer" href="https://www.instagram.com/p/ChTDNdHs6mU/">Ver en Instagram</a></p></li></ul>', 1, '/blog/mujeres-superpoderosas/imagen-para-blog-mxmas.png', 'Mujeres Superpoderosas', 'Mujeres x Más', '2022-03-30T12:22:28-03:00'::timestamptz),
  ('DA TUS PRIMEROS PASOS EN EL MUNDO DE LA PROGRAMACIÓN de la mano de Soy Henry & Mujeresxmas', 'cerramos-el-ano-con-una-mega-propuesta-de-la-mano-de-un-lider', 'Un curso gratuito y online para dar tus primeros pasos en programación: introducción a Javascript, en el tiempo que tengas libre y desde tu casa.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Queremos que sigas creciendo y para ello te proponemos sumarte a este curso en forma GRATUITA y ONLINE . Podrás hacerlo en el tiempo que tengas libre y desde la comodidad de tu casa."}]},{"type":"paragraph","content":[{"type":"text","text":"El curso es el punto de inicio de tu carrera: Introducción a conceptos básicos de Javascript."}]},{"type":"paragraph","content":[{"type":"text","text":"Una puerta a la programación (Duración 30 horas)."}]},{"type":"paragraph","content":[{"type":"text","text":"Solo hacen falta TUS GANAS para sumarte al Henry Challenge ."}]},{"type":"image","attrs":{"src":"/blog/cerramos-el-ano-con-una-mega-propuesta-de-la-mano-de-un-lider/cerramos-el-ano-con-una-mega-propuesta-de-la-mano-de-un-lider-1.jpg","alt":"Curso de introducción a Javascript de Soy Henry","title":null}},{"type":"paragraph","content":[{"type":"text","text":"Introducción a conceptos básicos de Javascript / una puerta a la programación (Duración 30 horas)","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Porque estudiar Tecnología:","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"🧠 Contarás con conocimiento transferible"}]},{"type":"paragraph","content":[{"type":"text","text":"🌈 No hay barreras y cualquiera puede estudiar"}]},{"type":"paragraph","content":[{"type":"text","text":"🆓Hay una enorme cantidad de puestos vacantes"}]},{"type":"paragraph","content":[{"type":"text","text":"🌎 Te permite trabajar desde cualquier lugar del mundo"}]},{"type":"paragraph","content":[{"type":"text","text":"🦾 Trabajarás en compañías tech de alto impacto que estás escribiendo el futuro."}]},{"type":"paragraph","content":[{"type":"text","text":"💛Los ambientes de trabajo son muy amigables"}]},{"type":"paragraph","content":[{"type":"text","text":"💸 Tendrás ingresos altos"}]},{"type":"paragraph","content":[{"type":"text","text":"📚 Aprenderás todo el tiempo"}]},{"type":"paragraph","content":[{"type":"text","text":"🎨Puedes crear lo que imagines"}]},{"type":"paragraph","content":[{"type":"text","text":"🧗‍♀️Asumirás muchos desafíos y podrás superarte día a día"}]},{"type":"image","attrs":{"src":"/blog/cerramos-el-ano-con-una-mega-propuesta-de-la-mano-de-un-lider/cerramos-el-ano-con-una-mega-propuesta-de-la-mano-de-un-lider-2.jpg","alt":"Soy Henry y Mujeres x Más","title":null}},{"type":"paragraph","content":[{"type":"text","text":"INSCRIBITE YA","marks":[{"type":"bold"}]}]}]}'::jsonb, '<p>Queremos que sigas creciendo y para ello te proponemos sumarte a este curso en forma GRATUITA y ONLINE . Podrás hacerlo en el tiempo que tengas libre y desde la comodidad de tu casa.</p><p>El curso es el punto de inicio de tu carrera: Introducción a conceptos básicos de Javascript.</p><p>Una puerta a la programación (Duración 30 horas).</p><p>Solo hacen falta TUS GANAS para sumarte al Henry Challenge .</p><img loading="lazy" src="/blog/cerramos-el-ano-con-una-mega-propuesta-de-la-mano-de-un-lider/cerramos-el-ano-con-una-mega-propuesta-de-la-mano-de-un-lider-1.jpg" alt="Curso de introducción a Javascript de Soy Henry"/><p><em>Introducción a conceptos básicos de Javascript / una puerta a la programación (Duración 30 horas)</em></p><p><strong>Porque estudiar Tecnología:</strong></p><p>🧠 Contarás con conocimiento transferible</p><p>🌈 No hay barreras y cualquiera puede estudiar</p><p>🆓Hay una enorme cantidad de puestos vacantes</p><p>🌎 Te permite trabajar desde cualquier lugar del mundo</p><p>🦾 Trabajarás en compañías tech de alto impacto que estás escribiendo el futuro.</p><p>💛Los ambientes de trabajo son muy amigables</p><p>💸 Tendrás ingresos altos</p><p>📚 Aprenderás todo el tiempo</p><p>🎨Puedes crear lo que imagines</p><p>🧗‍♀️Asumirás muchos desafíos y podrás superarte día a día</p><img loading="lazy" src="/blog/cerramos-el-ano-con-una-mega-propuesta-de-la-mano-de-un-lider/cerramos-el-ano-con-una-mega-propuesta-de-la-mano-de-un-lider-2.jpg" alt="Soy Henry y Mujeres x Más"/><p><strong>INSCRIBITE YA</strong></p>', 1, '/blog/cerramos-el-ano-con-una-mega-propuesta-de-la-mano-de-un-lider/soy-henry-y-mujerexmas.png', 'DA TUS PRIMEROS PASOS EN EL MUNDO DE LA PROGRAMACIÓN de la mano de Soy Henry & Mujeresxmas', 'Mujeres x Más', '2021-12-31T16:14:00-03:00'::timestamptz)
) as v (title, slug, excerpt, content, content_html, reading_minutes, cover_path, cover_alt, author_name, published_at);
